1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>AI app stack · Layer hierarchy</title>
7	  <link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Geist:wght@400;500;600&family=Geist+Mono:wght@400;500;600&display=swap" rel="stylesheet">
8	  <style>
9	    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
10	    :root {
11	      --color-paper:   #f5f5f5;
12	      --color-ink:     #2d3142;
13	      --color-muted:   #4f5d75;
14	      --color-accent:  #eb6c36;
15	      --font-sans:     'Geist', system-ui, sans-serif;
16	      --font-serif:    'Instrument Serif', serif;
17	      --font-mono:     'Geist Mono', ui-monospace, monospace;
18	    }
19	
20	    body {
21	      font-family: var(--font-sans);
22	      background: var(--color-paper);
23	      color: var(--color-ink);
24	      min-height: 100vh;
25	      display: flex;
26	      align-items: center;
27	      justify-content: center;
28	      padding: 3rem 2rem;
29	    }
30	
31	    .frame { max-width: 1200px; width: 100%; }
32	
33	    .eyebrow {
34	      font-family: var(--font-mono);
35	      font-size: 0.66rem;
36	      font-weight: 500;
37	      letter-spacing: 0.18em;
38	      text-transform: uppercase;
39	      color: var(--color-muted);
40	      margin-bottom: 0.5rem;
41	    }
42	
43	    h1 {
44	      font-family: var(--font-serif);
45	      font-size: clamp(1.5rem, 2.4vw + 0.75rem, 2rem);
46	      font-weight: 400;
47	      letter-spacing: -0.02em;
48	      line-height: 1.15;
49	      color: var(--color-ink);
50	      margin-bottom: 1.5rem;
51	    }
52	
53	    svg { width: 100%; min-width: 900px; display: block; }
54	  </style>
55	</head>
56	<body>
57	  <div class="frame">
58	    <p class="eyebrow">Layer stack · Diagram Design</p>
59	    <h1>AI app stack · Where the work actually happens</h1>
60	
61	    <svg viewBox="0 0 1000 500" xmlns="http://www.w3.org/2000/svg">
62	        <defs>
63	          <pattern id="dots" width="22" height="22" patternUnits="userSpaceOnUse">
64	            <circle cx="1" cy="1" r="0.9" fill="rgba(45,49,66,0.10)"/>
65	          </pattern>
66	        </defs>
67	
68	        <rect width="100%" height="100%" fill="#f5f5f5"/>
69	        <rect width="100%" height="100%" fill="url(#dots)" opacity="0.55"/>
70	
71	        <!-- Direction column (left margin) -->
72	        <text x="60" y="68" fill="#4f5d75" font-size="8" font-family="'Geist Mono', monospace" letter-spacing="0.18em">ABSTRACTION</text>
73	        <line x1="80" y1="80" x2="80" y2="400" stroke="rgba(45,49,66,0.30)" stroke-width="1"/>
74	        <polygon points="76,80 84,80 80,72" fill="#4f5d75"/>
75	        <text x="60" y="416" fill="#4f5d75" font-size="8" font-family="'Geist Mono', monospace" letter-spacing="0.18em">SILICON</text>
76	
77	        <!-- Stack container hairlines (top + bottom edges) -->
78	        <line x1="120" y1="80" x2="960" y2="80" stroke="rgba(45,49,66,0.12)" stroke-width="1"/>
79	        <line x1="120" y1="400" x2="960" y2="400" stroke="rgba(45,49,66,0.12)" stroke-width="1"/>
80	
81	        <!-- L5 — UI (top layer, near-white fill) -->
82	        <rect x="120" y="80" width="840" height="64" fill="#ffffff"/>
83	        <line x1="120" y1="144" x2="960" y2="144" stroke="rgba(45,49,66,0.12)" stroke-width="1"/>
84	        <text x="140" y="116" fill="#4f5d75" font-size="8" font-family="'Geist Mono', monospace" letter-spacing="0.14em">L5</text>
85	        <text x="260" y="118" fill="#2d3142" font-size="16" font-weight="600" font-family="'Geist', sans-serif">UI surface</text>
86	        <text x="940" y="118" fill="#4f5d75" font-size="10" font-family="'Geist Mono', monospace" text-anchor="end" letter-spacing="0.08em">chat, editor, canvas</text>
87	
88	        <!-- L4 — Agent harness (FOCAL, coral tint + coral stroke) -->
89	        <rect x="120" y="144" width="840" height="64" fill="rgba(235,108,54,0.08)"/>
90	        <rect x="120" y="144" width="840" height="64" fill="none" stroke="#eb6c36" stroke-width="1"/>
91	        <text x="140" y="180" fill="#eb6c36" font-size="8" font-family="'Geist Mono', monospace" letter-spacing="0.14em" font-weight="600">L4</text>
92	        <text x="260" y="182" fill="#2d3142" font-size="16" font-weight="600" font-family="'Geist', sans-serif">Agent harness</text>
93	        <text x="940" y="182" fill="#eb6c36" font-size="10" font-family="'Geist Mono', monospace" text-anchor="end" letter-spacing="0.08em">tools, memory, loop</text>
94	
95	        <!-- L3 — Prompt layer -->
96	        <rect x="120" y="208" width="840" height="64" fill="#f5f5f5"/>
97	        <line x1="120" y1="272" x2="960" y2="272" stroke="rgba(45,49,66,0.12)" stroke-width="1"/>
98	        <text x="140" y="244" fill="#4f5d75" font-size="8" font-family="'Geist Mono', monospace" letter-spacing="0.14em">L3</text>
99	        <text x="260" y="246" fill="#2d3142" font-size="16" font-weight="600" font-family="'Geist', sans-serif">Prompt layer</text>
100	        <text x="940" y="246" fill="#4f5d75" font-size="10" font-family="'Geist Mono', monospace" text-anchor="end" letter-spacing="0.08em">system, few-shot, caching</text>
101	
102	        <!-- L2 — SDK -->
103	        <rect x="120" y="272" width="840" height="64" fill="#ececec"/>
104	        <line x1="120" y1="336" x2="960" y2="336" stroke="rgba(45,49,66,0.12)" stroke-width="1"/>
105	        <text x="140" y="308" fill="#4f5d75" font-size="8" font-family="'Geist Mono', monospace" letter-spacing="0.14em">L2</text>
106	        <text x="260" y="310" fill="#2d3142" font-size="16" font-weight="600" font-family="'Geist', sans-serif">SDK / client</text>
107	        <text x="940" y="310" fill="#4f5d75" font-size="10" font-family="'Geist Mono', monospace" text-anchor="end" letter-spacing="0.08em">auth, retries, streaming</text>
108	
109	        <!-- L1 — Model -->
110	        <rect x="120" y="336" width="840" height="64" fill="#ececec"/>
111	        <text x="140" y="372" fill="#4f5d75" font-size="8" font-family="'Geist Mono', monospace" letter-spacing="0.14em">L1</text>
112	        <text x="260" y="374" fill="#2d3142" font-size="16" font-weight="600" font-family="'Geist', sans-serif">Model weights</text>
113	        <text x="940" y="374" fill="#4f5d75" font-size="10" font-family="'Geist Mono', monospace" text-anchor="end" letter-spacing="0.08em">opus, sonnet, haiku</text>
114	
115	        <!-- Caption -->
116	        <text x="120" y="456" fill="#4f5d75" font-size="8" font-family="'Geist Mono', monospace" letter-spacing="0.18em">FOCAL LAYER</text>
117	        <text x="240" y="456" fill="#4f5d75" font-size="8.5" font-family="'Geist', sans-serif" font-style="italic">The harness is where most product differentiation actually lives — tools, memory, and the loop that stitches model calls into useful work.</text>
118	      </svg>
119	  </div>
120	</body>
121	</html>
